/** The Neovim plugin's files, by path relative to the plugin root. */
export const NVIM_PLUGIN_FILES: Record<string, string> = {
  "README.md": "# hedgesync.nvim\n\nLive-edit HedgeDoc notes in Neovim, keystroke by keystroke, together with\npeople in the browser. Their edits appear in your buffer as they type, and\ntheir cursors are shown inline with their names.\n\nRequires Neovim 0.11+ and the `hedgesync` CLI.\n\n## Install\n\nThe plugin ships inside the `hedgesync` binary, so the two always match:\n\n```sh\n# 1. The CLI: a release binary (or `npm i -g hedgesync`)\ncurl -fL https://github.com/tionis/hedgesync/releases/latest/download/hedgesync-linux-x64 \\\n  -o ~/.local/bin/hedgesync && chmod +x ~/.local/bin/hedgesync\n\n# 2. The plugin, into Neovim's package directory\nhedgesync editor nvim install\n\n# 3. A login (the plugin uses the CLI's saved sessions)\nhedgesync login https://md.example.com --from-browser firefox --save   # or -u <user>\n```\n\nThen check everything with `:checkhealth hedgesync`. After updating the CLI,\nrun `hedgesync editor nvim install` again (`hedgesync editor nvim status`\ntells you whether you need to). Local edits to the installed plugin are never\noverwritten without `--force`. If the CLI and the plugin speak different\nprotocol versions, the plugin refuses to start and tells you which to update.\n\nNeovim loads the package directory by itself. lazy.nvim does not, so add a\nspec pointing at it (`install` prints it):\n\n```lua\n{\n  dir = vim.fn.stdpath(\"data\") .. \"/site/pack/hedgesync/start/hedgesync.nvim\",\n  name = \"hedgesync.nvim\",\n  cond = vim.uv.fs_stat(vim.fn.stdpath(\"data\") .. \"/site/pack/hedgesync/start/hedgesync.nvim\") ~= nil,\n  lazy = false,\n  opts = {},\n}\n```\n\nDon't lazy-load it on `BufReadCmd`: lazy.nvim then loads the plugin but does\nnot replay the `:e hedgedoc://...` that triggered it. Loading it eagerly costs\nnothing, because the startup file only defines `:Hedge` and an autocmd; the\nmodule loads on first use.\n\nTo hack on the plugin, point `dir` at `editors/nvim` in a checkout instead\nand run the CLI from the same checkout (`cmd = { \"bun\", \"<checkout>/bin/hedgesync.ts\" }`).\n\n## Use\n\n```vim\n:Hedge open https://md.example.com/abc123\n:e hedgedoc://md.example.com/abc123      \" same thing\n:Hedge users                              \" who has a cursor in the note\n:Hedge status\n:Hedge close                              \" stop syncing this buffer\n```\n\nThere is nothing to save: every change is sent as you make it, and `:w`\njust confirms the connection state. If the connection drops, keep typing;\nyour edits are sent once the bridge reconnects.\n\nFor a statusline: `require(\"hedgesync\").status()` returns e.g.\n`● connected`, and `b:hedgesync_title` holds the note title.\n\n## Options\n\n```lua\nrequire(\"hedgesync\").setup({\n  cmd = { \"hedgesync\" },   -- how to run the CLI, e.g. { \"bun\", \"/path/to/bin/hedgesync.ts\" }\n  args = {},               -- extra args for `hedgesync bridge`, e.g. { \"--cookie\", \"...\" }\n  cursors = true,          -- show other people's cursors\n  cursor_debounce = 50,    -- ms before sending your cursor position\n})\n```\n\n## How it works\n\nEach note buffer starts `hedgesync bridge <url>`, which holds the HedgeDoc\nconnection and exchanges newline-delimited JSON with the plugin. Because the\neditor and the bridge are separate processes, a remote edit can be in flight\nwhile you type; the bridge runs a second OT link toward the editor (all\ntransforming happens in the bridge; the plugin applies a remote edit only if\nit has typed nothing since, and the bridge resends dropped ones rebased). The\nprotocol is documented in `src/editor-bridge.ts`.\n\nThe plugin does not trust `on_bytes` for content: some commands (`J`, undo)\nreport changes before the buffer holds the new text. It keeps a snapshot of\nthe lines and diffs it against the buffer after each command instead. Every\nchange carries the buffer size, so if the two sides ever disagree the buffer\nis reset from the note rather than drifting.\n\n`HEDGESYNC_BRIDGE_LOG=/tmp/bridge.log nvim` traces the protocol.\n\n## Known limitations\n\n- `u` undoes other people's edits too when they are interleaved with yours:\n  Neovim has one undo history per buffer and cannot skip remote changes.\n- A note is shown with lines joined by `\\n`; `\\r\\n` line endings from\n  Windows clients show as `^M`.\n- Browsing notes (history picker) is not there yet; open notes by URL.\n",
  "lua/hedgesync/health.lua": "-- :checkhealth hedgesync\nlocal M = {}\n\nlocal function run(cmd, args)\n  local ok, proc = pcall(vim.system, vim.list_extend(vim.deepcopy(cmd), args), { text = true })\n  if not ok then\n    return nil, tostring(proc)\n  end\n  local result = proc:wait(15000)\n  if result.code ~= 0 then\n    return nil, vim.trim((result.stderr or \"\") .. (result.stdout or \"\"))\n  end\n  return result.stdout\nend\n\nlocal function read_json(path)\n  local f = io.open(path, \"r\")\n  if not f then\n    return nil\n  end\n  local ok, data = pcall(vim.json.decode, f:read(\"*a\"))\n  f:close()\n  return ok and data or nil\nend\n\nfunction M.check()\n  local h = vim.health\n  local hs = require(\"hedgesync\")\n  local cmd = hs.config.cmd\n\n  h.start(\"hedgesync.nvim\")\n  if vim.fn.has(\"nvim-0.11\") == 1 then\n    h.ok(\"Neovim \" .. tostring(vim.version()))\n  else\n    h.error(\"Neovim 0.11 or newer is required, this is \" .. tostring(vim.version()))\n  end\n\n  if vim.fn.executable(cmd[1]) ~= 1 then\n    h.error((\"`%s` is not on PATH\"):format(cmd[1]), {\n      \"Install the hedgesync CLI from https://github.com/tionis/hedgesync/releases (or `npm i -g hedgesync`)\",\n      \"or point `cmd` in require('hedgesync').setup() at it\",\n    })\n    return\n  end\n\n  local out, err = run(cmd, { \"bridge\", \"--info\" })\n  local info = out and pcall(vim.json.decode, out) and vim.json.decode(out) or nil\n  if not info then\n    h.error(\"`\" .. table.concat(cmd, \" \") .. \"` has no editor bridge (too old?)\", { \"Update the hedgesync CLI\", err })\n    return\n  end\n  if info.protocol == hs.protocol then\n    h.ok((\"hedgesync %s (%s), editor protocol %d\"):format(info.version, vim.fn.exepath(cmd[1]), info.protocol))\n  else\n    h.error(hs._protocol_problem(info.protocol, info.version))\n  end\n\n  local marker = read_json(hs.root .. \"/.hedgesync-install.json\")\n  if not marker then\n    h.info(\"Plugin loaded from \" .. hs.root .. \" (not installed by `hedgesync editor nvim install`)\")\n  elseif marker.version == info.version then\n    h.ok(\"Plugin installed by hedgesync \" .. marker.version .. \" in \" .. hs.root)\n  else\n    h.warn(\n      (\"Plugin was installed by hedgesync %s, the CLI is %s\"):format(tostring(marker.version), info.version),\n      { \"Run `hedgesync editor nvim install` to update the plugin\" }\n    )\n  end\n\n  h.start(\"hedgesync logins\")\n  local sessions_out = run(cmd, { \"sessions\", \"--json\" })\n  local ok, data = pcall(vim.json.decode, sessions_out or \"\")\n  local sessions = ok and type(data) == \"table\" and data.sessions or nil\n  if sessions == nil then\n    h.warn(\"Could not list saved logins (`hedgesync sessions --json` failed)\")\n  elseif #sessions == 0 then\n    h.warn(\"No saved logins; notes that need an account will be read-only or refused\", {\n      \"Run `hedgesync login <server> --from-browser firefox --save` (or `-u <user>` for email/LDAP)\",\n    })\n  else\n    for _, s in ipairs(sessions) do\n      local who = type(s.user) == \"table\" and s.user.name or s.user\n      h.ok((\"%s%s\"):format(s.server, who and (\" as \" .. tostring(who)) or \"\"))\n    end\n  end\n\n  h.start(\"hedgesync sessions in this Neovim\")\n  local any = false\n  for _, buf in ipairs(vim.api.nvim_list_bufs()) do\n    local s = hs.session(buf)\n    if s then\n      any = true\n      h.info((\"%s: %s\"):format(s.url, hs.status(buf)))\n    end\n  end\n  if not any then\n    h.info(\"No notes open\")\n  end\nend\n\nreturn M\n",
  "lua/hedgesync/init.lua": "-- hedgesync.nvim: live-edit HedgeDoc notes, keystroke by keystroke.\n--\n-- Each note buffer runs `hedgesync bridge <url>` and exchanges JSON lines with\n-- it. The bridge does all operational transformation; this side only reports\n-- buffer changes and applies remote edits whose `base` matches the\n-- number of changes it has sent, dropping stale ones (the bridge resends them\n-- rebased). See src/editor-bridge.ts for the protocol.\n\nlocal M = {}\n\n--- Editor protocol this plugin speaks (BRIDGE_PROTOCOL in src/editor-bridge.ts).\nM.protocol = 1\n\n--- Plugin root directory (holds .hedgesync-install.json when installed by\n--- `hedgesync editor nvim install`).\nM.root = vim.fn.fnamemodify(debug.getinfo(1, \"S\").source:sub(2), \":p:h:h:h\")\n\nM.config = {\n  -- Command that runs the hedgesync CLI.\n  cmd = { \"hedgesync\" },\n  -- Extra arguments for `hedgesync bridge` (e.g. { \"--cookie\", \"...\" }).\n  args = {},\n  -- Show other people's cursors.\n  cursors = true,\n  -- Delay before sending cursor moves (ms).\n  cursor_debounce = 50,\n}\n\nlocal api = vim.api\nlocal ns = api.nvim_create_namespace(\"hedgesync_cursors\")\n---@type table<integer, table>\nlocal sessions = {}\n\nlocal function notify(msg, level)\n  vim.notify(\"hedgesync: \" .. msg, level or vim.log.levels.INFO)\nend\n\nlocal function send(s, msg)\n  if s.closed or not s.proc then\n    return\n  end\n  local ok, err = pcall(function()\n    s.proc:write(vim.json.encode(msg) .. \"\\n\")\n  end)\n  if not ok then\n    s.closed = true\n    notify(\"bridge is gone: \" .. tostring(err), vim.log.levels.ERROR)\n  end\nend\n\nlocal function buf_size(buf)\n  return api.nvim_buf_get_offset(buf, api.nvim_buf_line_count(buf))\nend\n\nlocal function is_cont(str, i)\n  local b = str:byte(i)\n  return b ~= nil and b >= 0x80 and b < 0xC0\nend\n\n--- Row and byte column of byte offset `off` in `text`.\nlocal function rowcol(text, off)\n  local row, start = 0, 1\n  while true do\n    local nl = text:find(\"\\n\", start, true)\n    if not nl or nl > off then\n      break\n    end\n    row, start = row + 1, nl + 1\n  end\n  return row, off - (start - 1)\nend\n\n--- Report what changed since the last snapshot as one change message.\n---\n--- on_bytes only marks the buffer dirty: for some commands (J, for one) it\n--- fires before the buffer holds the new text, so the text is read here, once\n--- the command is done, by diffing against a snapshot of the lines. Lua\n--- interns strings, so unchanged lines compare in O(1).\nlocal function flush(s)\n  if not s.dirty then\n    return\n  end\n  s.dirty = false\n  local buf = s.buf\n  if s.closed or not api.nvim_buf_is_valid(buf) then\n    return\n  end\n  local old = s.lines\n  local new = api.nvim_buf_get_lines(buf, 0, -1, false)\n  local n_old, n_new = #old, #new\n  -- Compare from the top: on_bytes rows are not trustworthy either (undo).\n  local i = 0 -- 0-based first changed line\n  while i < n_old and i < n_new and old[i + 1] == new[i + 1] do\n    i = i + 1\n  end\n  local k = 0 -- unchanged lines at the end\n  while k < n_old - i and k < n_new - i and old[n_old - k] == new[n_new - k] do\n    k = k + 1\n  end\n  s.lines = new\n  if i == n_old - k and i == n_new - k then\n    return -- changed and changed back\n  end\n  -- The changed blocks, every line ending in \"\\n\" (the on_bytes model).\n  local o = table.concat(old, \"\\n\", i + 1, n_old - k) .. (n_old - k > i and \"\\n\" or \"\")\n  local n = table.concat(new, \"\\n\", i + 1, n_new - k) .. (n_new - k > i and \"\\n\" or \"\")\n  -- Narrow to the changed bytes, on UTF-8 character boundaries.\n  local p, max = 0, math.min(#o, #n)\n  while p < max and o:byte(p + 1) == n:byte(p + 1) do\n    p = p + 1\n  end\n  while p > 0 and (is_cont(o, p + 1) or is_cont(n, p + 1)) do\n    p = p - 1\n  end\n  local q = 0\n  while q < max - p and o:byte(#o - q) == n:byte(#n - q) do\n    q = q + 1\n  end\n  while q > 0 and is_cont(o, #o - q + 1) do\n    q = q - 1\n  end\n  local srow, scol = rowcol(o, p)\n  local erow, ecol = rowcol(o, #o - q)\n  s.E = s.E + 1\n  send(s, {\n    t = \"change\",\n    epoch = s.epoch,\n    seen = s.R,\n    sr = i + srow,\n    sc = scol,\n    oer = erow - srow,\n    oec = erow == srow and ecol - scol or ecol,\n    text = n:sub(p + 1, #n - q),\n    size = buf_size(buf),\n  })\n  vim.bo[buf].modified = false\nend\n\n--- Apply text without reporting it back to the bridge.\nlocal function apply(s, fn)\n  local buf = s.buf\n  local modifiable = vim.bo[buf].modifiable\n  s.applying = true\n  vim.bo[buf].modifiable = true\n  local ok, err = pcall(fn)\n  vim.bo[buf].modifiable = modifiable\n  s.applying = false\n  vim.bo[buf].modified = false\n  s.lines = api.nvim_buf_get_lines(buf, 0, -1, false)\n  return ok, err\nend\n\nlocal function set_modifiable(s)\n  vim.bo[s.buf].modifiable = s.editable and not s.closed\n  vim.bo[s.buf].readonly = not s.editable\nend\n\nlocal function update_status(s, state)\n  s.state = state\n  vim.b[s.buf].hedgesync_state = state\n  vim.cmd.redrawstatus()\nend\n\n-- Remote cursors -----------------------------------------------------------\n\nlocal hl_cache = {}\n\n--- \"#rgb\" / \"#rrggbb\" (HedgeDoc sends both) as \"#rrggbb\", or nil.\nlocal function normalize_color(color)\n  local hex = type(color) == \"string\" and color:match(\"^#?(%x+)$\")\n  if hex and #hex == 3 then\n    hex = hex:gsub(\".\", \"%0%0\")\n  end\n  return hex and #hex == 6 and (\"#\" .. hex:lower()) or nil\nend\n\nlocal function cursor_hl(color)\n  color = normalize_color(color) or \"#888888\"\n  local name = \"HedgesyncCursor_\" .. color:sub(2)\n  if not hl_cache[name] then\n    local r, g, b = tonumber(color:sub(2, 3), 16), tonumber(color:sub(4, 5), 16), tonumber(color:sub(6, 7), 16)\n    local fg = (0.299 * r + 0.587 * g + 0.114 * b) > 140 and \"#000000\" or \"#ffffff\"\n    api.nvim_set_hl(0, name, { bg = color, fg = fg })\n    api.nvim_set_hl(0, name .. \"Label\", { fg = color, italic = true })\n    hl_cache[name] = true\n  end\n  return name\nend\n\nlocal function draw_cursors(s, cursors)\n  local buf = s.buf\n  api.nvim_buf_clear_namespace(buf, ns, 0, -1)\n  if not M.config.cursors then\n    return\n  end\n  local line_count = api.nvim_buf_line_count(buf)\n  for _, c in ipairs(cursors) do\n    if c.row < line_count then\n      local line = api.nvim_buf_get_lines(buf, c.row, c.row + 1, false)[1] or \"\"\n      local col = math.min(c.col, #line)\n      local hl = cursor_hl(c.color or \"#888888\")\n      local opts = {\n        virt_text = { { \" \" .. c.name, hl .. \"Label\" } },\n        virt_text_pos = \"eol\",\n        priority = 200,\n      }\n      if col < #line then\n        -- Highlight the character under the cursor (one UTF-8 character).\n        local char_end = vim.str_byteindex(line, \"utf-32\", vim.str_utfindex(line, \"utf-32\", col) + 1, false)\n        opts.end_col = char_end\n        opts.hl_group = hl\n      else\n        opts.virt_text = { { \" \", hl }, { \" \" .. c.name, hl .. \"Label\" } }\n        opts.virt_text_pos = \"overlay\"\n      end\n      pcall(api.nvim_buf_set_extmark, buf, ns, c.row, col, opts)\n    end\n  end\nend\n\n-- Messages from the bridge -------------------------------------------------\n\nlocal function on_reset(s, msg)\n  flush(s) -- dropped anyway (new epoch), but keeps the snapshot honest\n  local buf = s.buf\n  local first = not s.loaded\n  local view = vim.fn.bufwinid(buf) ~= -1 and vim.fn.winsaveview() or nil\n  local undolevels = vim.bo[buf].undolevels\n  if first then\n    vim.bo[buf].undolevels = -1 -- loading the note is not an undoable change\n  end\n  apply(s, function()\n    api.nvim_buf_set_lines(buf, 0, -1, false, vim.split(msg.text, \"\\n\", { plain = true }))\n  end)\n  if first then\n    vim.bo[buf].undolevels = undolevels\n  end\n  s.epoch, s.E, s.R, s.loaded = msg.epoch, 0, msg.seq, true\n  if view and not first and api.nvim_get_current_buf() == buf then\n    pcall(vim.fn.winrestview, view)\n  end\nend\n\nlocal function on_edit(s, msg)\n  flush(s) -- unreported local changes make this edit stale\n  if msg.base ~= s.E then\n    return -- typed something since; the bridge will resend this rebased\n  end\n  local ok, err = apply(s, function()\n    for _, e in ipairs(msg.edits) do\n      api.nvim_buf_set_text(s.buf, e.sr, e.sc, e.er, e.ec, vim.split(e.text, \"\\n\", { plain = true }))\n    end\n  end)\n  if not ok then\n    notify(\"could not apply a remote edit (\" .. tostring(err) .. \"); resyncing\", vim.log.levels.WARN)\n    send(s, { t = \"desync\" })\n    return\n  end\n  s.R = msg.seq\nend\n\n--- Why a bridge with protocol `theirs` cannot be used, and what to do.\nlocal function protocol_problem(theirs, version)\n  local fix = (theirs or 0) < M.protocol and \"update the hedgesync CLI\"\n    or \"run `hedgesync editor nvim install` to update this plugin\"\n  return (\"hedgesync %s speaks editor protocol %s, this plugin speaks %d: %s\"):format(\n    version or \"(unknown version)\",\n    tostring(theirs or \"none\"),\n    M.protocol,\n    fix\n  )\nend\nM._protocol_problem = protocol_problem\n\nlocal handlers = {\n  ready = function(s, msg)\n    if msg.protocol ~= M.protocol then\n      notify(protocol_problem(msg.protocol, msg.version), vim.log.levels.ERROR)\n      M.close(s.buf)\n      return\n    end\n    s.editable = msg.editable\n    s.title = msg.title\n    vim.b[s.buf].hedgesync_title = msg.title\n    set_modifiable(s)\n    update_status(s, \"connected\")\n    if not msg.editable then\n      notify(\"note is read-only for you\", vim.log.levels.WARN)\n    end\n  end,\n  note = function(s, msg)\n    s.title = msg.title\n    vim.b[s.buf].hedgesync_title = msg.title\n    if msg.editable ~= s.editable then\n      s.editable = msg.editable\n      set_modifiable(s)\n      notify(msg.editable and \"note is editable again\" or \"note is now read-only for you\", vim.log.levels.WARN)\n    end\n  end,\n  reset = on_reset,\n  edit = on_edit,\n  cursors = function(s, msg)\n    s.cursors = msg.cursors\n    draw_cursors(s, msg.cursors)\n  end,\n  status = function(s, msg)\n    if msg.state == \"desync\" then\n      notify(msg.message or \"buffer resynchronised\", vim.log.levels.WARN)\n    else\n      if msg.state == \"disconnected\" then\n        notify(\"disconnected; edits are kept and sent on reconnect\", vim.log.levels.WARN)\n      elseif msg.state == \"connected\" and s.state ~= \"connected\" then\n        notify(\"reconnected\")\n      end\n      update_status(s, msg.state)\n    end\n  end,\n  error = function(s, msg)\n    notify(msg.message, vim.log.levels.ERROR)\n  end,\n}\n\nlocal function dispatch(s, line)\n  local ok, msg = pcall(vim.json.decode, line, { luanil = { object = true, array = true } })\n  if not ok or type(msg) ~= \"table\" then\n    return\n  end\n  local handler = handlers[msg.t]\n  if handler and api.nvim_buf_is_valid(s.buf) then\n    handler(s, msg)\n  end\nend\n\n-- Buffer events ------------------------------------------------------------\n\nlocal function attach(s)\n  api.nvim_buf_attach(s.buf, false, {\n    on_bytes = function()\n      if s.closed then\n        return true -- detach\n      end\n      if s.applying or not s.loaded then\n        return\n      end\n      if not s.dirty then\n        s.dirty = true\n        vim.schedule(function()\n          flush(s)\n        end)\n      end\n    end,\n    on_detach = function()\n      s.closed = true\n    end,\n  })\n\n  local group = api.nvim_create_augroup(\"hedgesync_buf_\" .. s.buf, { clear = true })\n  local timer = vim.uv.new_timer()\n  s.cursor_timer = timer\n  local function send_cursor()\n    if not s.loaded or api.nvim_get_current_buf() ~= s.buf then\n      return\n    end\n    flush(s)\n    local pos = api.nvim_win_get_cursor(0)\n    send(s, { t = \"cursor\", epoch = s.epoch, seen = s.R, row = pos[1] - 1, col = pos[2] })\n  end\n  api.nvim_create_autocmd({ \"CursorMoved\", \"CursorMovedI\" }, {\n    group = group,\n    buffer = s.buf,\n    callback = function()\n      timer:stop()\n      timer:start(M.config.cursor_debounce, 0, vim.schedule_wrap(send_cursor))\n    end,\n  })\n  api.nvim_create_autocmd(\"BufEnter\", { group = group, buffer = s.buf, callback = send_cursor })\n  api.nvim_create_autocmd(\"BufLeave\", {\n    group = group,\n    buffer = s.buf,\n    callback = function()\n      send(s, { t = \"cursor\", row = vim.NIL })\n    end,\n  })\n  api.nvim_create_autocmd(\"BufWriteCmd\", {\n    group = group,\n    buffer = s.buf,\n    callback = function()\n      vim.bo[s.buf].modified = false\n      notify(s.state == \"connected\" and \"changes are synced live\" or (\"not connected (\" .. tostring(s.state) .. \")\"))\n    end,\n  })\n  api.nvim_create_autocmd({ \"BufWipeout\", \"BufDelete\" }, {\n    group = group,\n    buffer = s.buf,\n    callback = function()\n      M.close(s.buf)\n    end,\n  })\nend\n\n-- Public API ---------------------------------------------------------------\n\nlocal function buf_name(url)\n  return \"hedgedoc://\" .. url:gsub(\"^https?://\", \"\")\nend\n\n--- Open a note for live editing in the current window. Returns the buffer.\nfunction M.open(url)\n  url = vim.trim(url or \"\")\n  if url == \"\" then\n    notify(\"usage: :Hedge open <note url>\", vim.log.levels.ERROR)\n    return\n  end\n  if url:match(\"^hedgedoc://\") then\n    local rest = url:gsub(\"^hedgedoc://\", \"\")\n    local scheme = (rest:match(\"^localhost\") or rest:match(\"^127%.\")) and \"http://\" or \"https://\"\n    url = scheme .. rest\n  end\n  for buf, s in pairs(sessions) do\n    if s.url == url and api.nvim_buf_is_valid(buf) then\n      api.nvim_set_current_buf(buf)\n      return buf\n    end\n  end\n\n  local name = buf_name(url)\n  local buf = vim.fn.bufnr(name)\n  if buf == -1 or not api.nvim_buf_is_valid(buf) then\n    buf = api.nvim_create_buf(true, false)\n    api.nvim_buf_set_name(buf, name)\n  end\n  vim.bo[buf].buftype = \"acwrite\"\n  vim.bo[buf].swapfile = false\n  vim.bo[buf].modifiable = false\n  vim.bo[buf].filetype = \"markdown\"\n  api.nvim_set_current_buf(buf)\n\n  local s = {\n    buf = buf,\n    url = url,\n    E = 0,\n    R = 0,\n    epoch = 0,\n    loaded = false,\n    editable = false,\n    state = \"connecting\",\n    lines = {},\n  }\n  sessions[buf] = s\n  update_status(s, \"connecting\")\n  attach(s)\n\n  local cmd = vim.list_extend(vim.list_extend(vim.deepcopy(M.config.cmd), { \"bridge\", url }), M.config.args)\n  local pending = \"\"\n  local stderr = {}\n  local ok, proc = pcall(vim.system, cmd, {\n    stdin = true,\n    stdout = function(_, data)\n      if not data then\n        return\n      end\n      pending = pending .. data\n      local lines = vim.split(pending, \"\\n\", { plain = true })\n      pending = table.remove(lines)\n      for _, line in ipairs(lines) do\n        if line ~= \"\" then\n          vim.schedule(function()\n            dispatch(s, line)\n          end)\n        end\n      end\n    end,\n    stderr = function(_, data)\n      if data then\n        table.insert(stderr, data)\n      end\n    end,\n  }, function(result)\n    vim.schedule(function()\n      local was_closed = s.closed\n      s.closed = true\n      s.proc = nil\n      if api.nvim_buf_is_valid(buf) then\n        set_modifiable(s)\n        update_status(s, \"closed\")\n        api.nvim_buf_clear_namespace(buf, ns, 0, -1)\n      end\n      if not was_closed and result.code ~= 0 then\n        local err = vim.trim(table.concat(stderr))\n        if err:find(\"Unknown command: bridge\", 1, true) then\n          notify(\"your hedgesync CLI is too old for this plugin (no `bridge` command); update it\", vim.log.levels.ERROR)\n          return\n        end\n        notify(\"bridge exited (\" .. result.code .. \")\" .. (err ~= \"\" and (\":\\n\" .. err) or \"\"), vim.log.levels.ERROR)\n      end\n    end)\n  end)\n  if not ok then\n    sessions[buf] = nil\n    notify(\"could not start \" .. table.concat(cmd, \" \") .. \": \" .. tostring(proc), vim.log.levels.ERROR)\n    return\n  end\n  s.proc = proc\n  return buf\nend\n\n--- Stop syncing a buffer (edits made so far are flushed by the bridge).\nfunction M.close(buf)\n  buf = (buf == nil or buf == 0) and api.nvim_get_current_buf() or buf\n  local s = sessions[buf]\n  if not s then\n    return\n  end\n  sessions[buf] = nil\n  if s.cursor_timer then\n    s.cursor_timer:stop()\n    s.cursor_timer:close()\n  end\n  if s.proc and not s.closed then\n    flush(s)\n    send(s, { t = \"close\" })\n    pcall(function()\n      s.proc:write(nil)\n    end)\n  end\n  s.closed = true\n  if api.nvim_buf_is_valid(buf) then\n    pcall(api.nvim_buf_clear_namespace, buf, ns, 0, -1)\n    pcall(api.nvim_del_augroup_by_name, \"hedgesync_buf_\" .. buf)\n    vim.bo[buf].modifiable = false\n  end\nend\n\n--- Close all sessions and wait (briefly) for the bridges to flush.\nfunction M.close_all(timeout)\n  local procs = {}\n  for buf, s in pairs(sessions) do\n    if s.proc then\n      table.insert(procs, s.proc)\n    end\n    M.close(buf)\n  end\n  for _, proc in ipairs(procs) do\n    pcall(function()\n      proc:wait(timeout or 3000)\n    end)\n  end\nend\n\n--- Session for a buffer (for statuslines and tests).\nfunction M.session(buf)\n  return sessions[(buf == nil or buf == 0) and api.nvim_get_current_buf() or buf]\nend\n\n--- Short status for statuslines, e.g. \"● connected\".\nfunction M.status(buf)\n  local s = M.session(buf)\n  if not s then\n    return \"\"\n  end\n  local icon = ({ connected = \"●\", connecting = \"◌\", reconnecting = \"◌\", disconnected = \"○\", closed = \"×\" })[s.state]\n    or \"?\"\n  return icon .. \" \" .. tostring(s.state)\nend\n\nfunction M.users(buf)\n  local s = M.session(buf)\n  if not s then\n    notify(\"not a hedgesync buffer\", vim.log.levels.WARN)\n    return\n  end\n  local names = {}\n  for _, c in ipairs(s.cursors or {}) do\n    table.insert(names, (\"%s (line %d)\"):format(c.name, c.row + 1))\n  end\n  notify(#names > 0 and (\"editing here: \" .. table.concat(names, \", \")) or \"nobody else has a cursor in this note\")\nend\n\nfunction M.setup(opts)\n  M.config = vim.tbl_deep_extend(\"force\", M.config, opts or {})\nend\n\nreturn M\n",
  "plugin/hedgesync.lua": "if vim.g.loaded_hedgesync then\n  return\nend\nvim.g.loaded_hedgesync = true\n\nlocal subcommands = {\n  open = function(args)\n    require(\"hedgesync\").open(args)\n  end,\n  close = function()\n    require(\"hedgesync\").close(0)\n  end,\n  users = function()\n    require(\"hedgesync\").users(0)\n  end,\n  status = function()\n    vim.notify(require(\"hedgesync\").status(0))\n  end,\n}\n\nvim.api.nvim_create_user_command(\"Hedge\", function(opts)\n  local sub, rest = opts.args:match(\"^(%S+)%s*(.*)$\")\n  local fn = subcommands[sub or \"\"]\n  if not fn then\n    vim.notify(\"usage: :Hedge open <url> | close | users | status\", vim.log.levels.ERROR)\n    return\n  end\n  fn(rest)\nend, {\n  nargs = \"+\",\n  complete = function(arglead, line)\n    if line:match(\"^%S+%s+%S*$\") then\n      return vim.tbl_filter(function(name)\n        return name:find(arglead, 1, true) == 1\n      end, vim.tbl_keys(subcommands))\n    end\n    return {}\n  end,\n})\n\n-- :e hedgedoc://md.example.com/abc123\nvim.api.nvim_create_autocmd(\"BufReadCmd\", {\n  pattern = \"hedgedoc://*\",\n  callback = function(ev)\n    local hs = require(\"hedgesync\")\n    if hs.session(ev.buf) then\n      return\n    end\n    local name = vim.api.nvim_buf_get_name(ev.buf)\n    local buf = ev.buf\n    vim.schedule(function()\n      hs.open(name)\n      -- open() created or reused its own buffer; drop the placeholder.\n      if vim.api.nvim_buf_is_valid(buf) and not hs.session(buf) then\n        pcall(vim.api.nvim_buf_delete, buf, { force = true })\n      end\n    end)\n  end,\n})\n\nvim.api.nvim_create_autocmd(\"VimLeavePre\", {\n  callback = function()\n    if package.loaded[\"hedgesync\"] then\n      require(\"hedgesync\").close_all(3000)\n    end\n  end,\n})\n",
};
